mapper.select:
SELECT
    a.*
FROM swm_hazard_source a

    ${sqlMap.dsf}

        AND a.hazard_name LIKE #{hazardName}


        AND a.hazard_category = #{hazardCategory}


        AND a.location LIKE #{location}


        AND a.beacon_identifier LIKE #{beaconIdentifier}


        AND a.is_patrol_included = #{isPatrolIncluded}


        AND a.hazard_status = #{hazardStatus}


        AND a.status = #{status}


ORDER BY a.create_date DESC

SELECT COUNT(*)
FROM swm_hazard_source
WHERE hazard_status = #{status}
  AND YEAR(registration_time) = #{year}
  AND MONTH(registration_time) = #{month}
